-- REVIEW ONLY. One CREATE OR REPLACE statement. Execute as SQL script in DBeaver.
USE auxiliares;
DELIMITER $$
CREATE OR REPLACE TRIGGER `TRG_FB_DOMICILIOS_HIST_UPDATE` AFTER UPDATE ON `FB_DOMICILIOS` FOR EACH ROW
BEGIN
IF NEW.VERSION>OLD.VERSION THEN INSERT INTO FB_DOMICILIOS_HISTORIAL (ID_DOMICILIO,ID_CONSULTA,VERSION,USUARIO_MODIFICADOR_ID,DATOS_ANTERIORES,DATOS_NUEVOS) VALUES (NEW.ID_DOMICILIO,NEW.ID_CONSULTA,NEW.VERSION,NEW.USUARIO_MODIFICADOR_ID,JSON_OBJECT('id_domicilio',CAST(OLD.`ID_DOMICILIO` AS CHAR),'id_persona',CAST(OLD.`ID_PERSONA` AS CHAR),'id_persona_cp',CAST(OLD.`ID_PERSONA_CP` AS CHAR),'id_domicilio_cp',CAST(OLD.`ID_DOMICILIO_CP` AS CHAR),'id_consulta',CAST(OLD.`ID_CONSULTA` AS CHAR),'calle',OLD.`CALLE`,'numero',OLD.`NUMERO`,'barrio',OLD.`BARRIO`,'localidad',OLD.`LOCALIDAD`,'departamento',OLD.`DEPARTAMENTO`,'codigo_postal',OLD.`CODIGO_POSTAL`,'ph',OLD.`PH`,'block',OLD.`BLOCK`,'depto',OLD.`DEPTO`,'puerta',OLD.`PUERTA`,'domicilio_completo',OLD.`DOMICILIO_COMPLETO`,'referencia',OLD.`REFERENCIA`,'sector',OLD.`SECTOR`,'manzana',OLD.`MANZANA`,'lote',OLD.`LOTE`,'version',OLD.`VERSION`,'fecha_alta',OLD.`FECHA_ALTA`,'fecha_modificacion',OLD.`FECHA_MODIFICACION`,'usuario_modificador_id',OLD.`USUARIO_MODIFICADOR_ID`,'verificacion_cp_json',JSON_QUERY(OLD.`VERIFICACION_CP_JSON`,'$')),JSON_OBJECT('id_domicilio',CAST(NEW.`ID_DOMICILIO` AS CHAR),'id_persona',CAST(NEW.`ID_PERSONA` AS CHAR),'id_persona_cp',CAST(NEW.`ID_PERSONA_CP` AS CHAR),'id_domicilio_cp',CAST(NEW.`ID_DOMICILIO_CP` AS CHAR),'id_consulta',CAST(NEW.`ID_CONSULTA` AS CHAR),'calle',NEW.`CALLE`,'numero',NEW.`NUMERO`,'barrio',NEW.`BARRIO`,'localidad',NEW.`LOCALIDAD`,'departamento',NEW.`DEPARTAMENTO`,'codigo_postal',NEW.`CODIGO_POSTAL`,'ph',NEW.`PH`,'block',NEW.`BLOCK`,'depto',NEW.`DEPTO`,'puerta',NEW.`PUERTA`,'domicilio_completo',NEW.`DOMICILIO_COMPLETO`,'referencia',NEW.`REFERENCIA`,'sector',NEW.`SECTOR`,'manzana',NEW.`MANZANA`,'lote',NEW.`LOTE`,'version',NEW.`VERSION`,'fecha_alta',NEW.`FECHA_ALTA`,'fecha_modificacion',NEW.`FECHA_MODIFICACION`,'usuario_modificador_id',NEW.`USUARIO_MODIFICADOR_ID`,'verificacion_cp_json',JSON_QUERY(NEW.`VERIFICACION_CP_JSON`,'$'))); END IF;
END$$
DELIMITER ;
